"""PostgreSQL customer store; configure CUSTOMER_STORE_DSN before use."""
import os

import psycopg


def _connect():
    dsn = os.environ.get("CUSTOMER_STORE_DSN")
    if not dsn:
        raise RuntimeError("Set CUSTOMER_STORE_DSN to the PostgreSQL connection string")
    return psycopg.connect(dsn)


def _initialize(db):
    db.execute("CREATE TABLE IF NOT EXISTS customers (id BIGINT PRIMARY KEY, name TEXT NOT NULL)")


def initialize():
    with _connect() as db:
        _initialize(db)


def add_customer(customer_id, name):
    with _connect() as db:
        db.execute("INSERT INTO customers (id, name) VALUES (%s, %s)", (customer_id, name))


def list_customers():
    with _connect() as db:
        return [{"id": row[0], "name": row[1]} for row in db.execute("SELECT id, name FROM customers ORDER BY id")]
